<script setup lang="ts">
useSeoMeta({title:'验证邮箱 · DevStore'});
const route=useRoute();const router=useRouter();const api=useApi();const message=ref('正在验证邮箱…');const failed=ref(false);const email=ref('');const resendMessage=ref('');const resendError=ref('');
onMounted(async()=>{const token=typeof route.query.token==='string'?route.query.token:'';if(!token){message.value='验证链接无效或已过期。';failed.value=true;return;}await router.replace('/verify-email');try{await api.request('/auth/verify-email',{method:'POST',body:{token}});message.value='邮箱验证成功，现在可以登录。';}catch{message.value='验证链接无效或已过期。';failed.value=true;}});
async function resend(){resendError.value='';resendMessage.value='';try{const result=await api.request<{message:string}>('/auth/verify-email/resend',{method:'POST',body:{email:email.value}});resendMessage.value=result.message;}catch(e){resendError.value=e instanceof Error?e.message:'请求失败，请重试';}}
</script>
<template><div class="container"><section class="auth-page panel"><span class="eyebrow">EMAIL VERIFICATION</span><h1>邮箱验证</h1><p :role="failed?'alert':'status'" class="muted">{{ message }}</p><NuxtLink v-if="!failed" class="btn" to="/login">前往登录</NuxtLink><template v-else><form @submit.prevent="resend"><div class="field"><label for="email">邮箱</label><input id="email" v-model="email" type="email" maxlength="255" autocomplete="email" required></div><p v-if="resendError" role="alert" class="error">{{ resendError }}</p><p v-if="resendMessage" role="status" class="muted">{{ resendMessage }}</p><button class="btn">重新发送验证邮件</button></form><NuxtLink class="text-link" to="/register">返回注册</NuxtLink></template></section></div></template>
